self.addEventListener('install', function (e) {
  e.waitUntil(caches.open(CORE).then(function (c) {
    // one by one, so a single missing file does not block the rest
    return Promise.all(FILES.map(function (f) {
      return fetch(f, { cache: 'reload' }).then(function (r) { if (r.ok) return c.put(f, r); }).catch(function () {});
    }));
  }).then(function () { return self.skipWaiting(); }));
});

self.addEventListener('activate', function (e) {
  e.waitUntil(caches.keys().then(function (keys) {
    return Promise.all(keys.filter(function (k) { return k.indexOf('bio02-core-') === 0 && k !== CORE; })
      .map(function (k) { return caches.delete(k); }));
  }).then(function () { return self.clients.claim(); }));
});

self.addEventListener('fetch', function (e) {
  var req = e.request;
  if (req.method !== 'GET') return;
  var url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  if (req.headers.get('range')) return; // audio seeking: let the network handle it
  e.respondWith(
    caches.match(url.pathname.slice(-1) === '/' ? url.pathname + 'index.html' : req, { ignoreSearch: true }).then(function (hit) {
      if (hit) return hit;
      return fetch(req).then(function (r) {
        if (r.ok && r.status === 200 && r.type === 'basic') {
          var copy = r.clone();
          caches.open(EXTRA).then(function (c) { c.put(req, copy); });
        }
        return r;
      }).catch(function () {
        if (req.mode === 'navigate') return caches.match('quiz/index.html');
        return new Response('', { status: 504, statusText: 'offline' });
      });
    })
  );
});
